<?php
namespace App\Http\Controllers\Api\V1\Purchasing;
use App\Http\Controllers\Controller; use App\Http\Requests\Api\V1\Purchasing\{ExecutionIndexRequest,StoreExecutionRequest,UpdateExecutionRequest,PostExecutionRequest}; use App\Services\Purchasing\ExecutionWorkflowService; use Illuminate\Http\JsonResponse;
class ExecutionWorkflowController extends Controller { public function __construct(private ExecutionWorkflowService $service){} private function ok($data):JsonResponse{return response()->json(['success'=>true,'data'=>$data]);} public function catalogs(string $kind):JsonResponse{return $this->ok($this->service->catalogs($kind));} public function index(ExecutionIndexRequest $r,string $kind):JsonResponse{return $this->ok($this->service->list($kind,$r->validated()));} public function store(StoreExecutionRequest $r,string $kind):JsonResponse{return $this->ok($this->service->store($kind,$r->validated(),$r->user()));} public function show(string $kind,string $id):JsonResponse{return $this->ok($this->service->show($kind,$id));} public function update(UpdateExecutionRequest $r,string $kind,string $id):JsonResponse{return $this->ok($this->service->update($kind,$id,$r->validated(),$r->user()));} public function post(PostExecutionRequest $r,string $kind,string $id):JsonResponse{return $this->ok($this->service->post($kind,$id,$r->validated(),$r->user()));} }
